-- Enable extensions (PostgreSQL specific)\nCREATE EXTENSION IF NOT EXISTS "uuid-ossp";\n\n-- Users table – core identity information\nCREATE TABLE users (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    email VARCHAR(255) NOT NULL UNIQUE,\n    password_hash VARCHAR(255) NOT NULL,\n    full_name VARCHAR(255),\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()\n);\n\n-- Wallets belong to a user and can contain multiple addresses\nCREATE TABLE wallets (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n    name VARCHAR(100) NOT NULL,\n    description TEXT,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\n    UNIQUE(user_id, name)\n);\n\n-- Individual blockchain addresses linked to a wallet\nCREATE TABLE wallet_addresses (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    wallet_id UUID NOT NULL REFERENCES wallets(id) ON DELETE CASCADE,\n    address VARCHAR(42) NOT NULL,\n    chain_id VARCHAR(20) NOT NULL,\n    is_default BOOLEAN NOT NULL DEFAULT FALSE,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\n    UNIQUE(wallet_id, address)\n);\n\n-- Token metadata (ERC‑20, SPL, etc.)\nCREATE TABLE tokens (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    symbol VARCHAR(10) NOT NULL,\n    name VARCHAR(50) NOT NULL,\n    decimals SMALLINT NOT NULL,\n    contract_address VARCHAR(42),\n    chain_id VARCHAR(20) NOT NULL,\n    UNIQUE(chain_id, contract_address)\n);\n\n-- Balance per address per token – high‑precision numeric\nCREATE TABLE token_balances (\n    wallet_address_id UUID NOT NULL REFERENCES wallet_addresses(id) ON DELETE CASCADE,\n    token_id UUID NOT NULL REFERENCES tokens(id) ON DELETE CASCADE,\n    balance NUMERIC(78,0) NOT NULL DEFAULT 0,\n    last_updated TIMESTAMP WITH TIME ZONE DEFAULT now(),\n    PRIMARY KEY (wallet_address_id, token_id)\n);\n\n-- Transaction history (on‑chain and off‑chain events)\nCREATE TABLE transactions (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    wallet_address_id UUID NOT NULL REFERENCES wallet_addresses(id) ON DELETE CASCADE,\n    tx_hash VARCHAR(66) NOT NULL UNIQUE,\n    block_number BIGINT,\n    nonce BIGINT,\n    from_address VARCHAR(42) NOT NULL,\n    to_address VARCHAR(42),\n    token_id UUID REFERENCES tokens(id),\n    amount NUMERIC(78,0) NOT NULL,\n    gas_price NUMERIC(78,0),\n    gas_used BIGINT,\n    status VARCHAR(20) NOT NULL CHECK (status IN ('pending','confirmed','failed')),
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()\n);\n\n-- Indexes for fast lookup\nCREATE INDEX idx_transactions_wallet_address ON transactions(wallet_address_id);\nCREATE INDEX idx_transactions_timestamp ON transactions(timestamp);\nCREATE INDEX idx_transactions_status ON transactions(status);\n\n-- User notifications (in‑app, email, push)\nCREATE TABLE notifications (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n    type VARCHAR(30) NOT NULL,\n    payload JSONB NOT NULL,\n    is_read BOOLEAN NOT NULL DEFAULT FALSE,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()\n);\n\n-- Persistent user settings\nCREATE TABLE user_settings (\n    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,\n    theme VARCHAR(20) NOT NULL DEFAULT 'dark',\n    currency VARCHAR(10) NOT NULL DEFAULT 'USD',\n    language VARCHAR(10) NOT NULL DEFAULT 'en',\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()\n);\n\n-- Trigger function to keep updated_at columns fresh\nCREATE OR REPLACE FUNCTION update_timestamp()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_users_updated\nBEFORE UPDATE ON users\nFOR EACH ROW EXECUTE FUNCTION update_timestamp();\n\nCREATE TRIGGER trg_wallets_updated\nBEFORE UPDATE ON wallets\nFOR EACH ROW EXECUTE FUNCTION update_timestamp();\n\nCREATE TRIGGER trg_wallet_addresses_updated\nBEFORE UPDATE ON wallet_addresses\nFOR EACH ROW EXECUTE FUNCTION update_timestamp();\n\nCREATE TRIGGER trg_user_settings_updated\nBEFORE UPDATE ON user_settings\nFOR EACH ROW EXECUTE FUNCTION update_timestamp();\n\n-- View to aggregate a user’s portfolio across all addresses\nCREATE OR REPLACE VIEW user_portfolio AS\nSELECT\n    u.id AS user_id,\n    t.symbol,\n    t.name,\n    SUM(tb.balance) AS total_balance,\n    MAX(t.decimals) AS decimals\nFROM users u\nJOIN wallets w ON w.user_id = u.id\nJOIN wallet_addresses wa ON wa.wallet_id = w.id\nJOIN token_balances tb ON tb.wallet_address_id = wa.id\nJOIN tokens t ON t.id = tb.token_id\nGROUP BY u.id, t.symbol, t.name;\n